      '"""LFS transfer-token minting and verification."""',
      "from __future__ import annotations",
      "",
      "import hashlib",
      "import hmac",
      "import time",
      "from dataclasses import dataclass",
      "",
      "from app.core.errors import ForbiddenError",
      "from app.services.lfs_store import LfsObject  # noqa: F401",
      "",
      "",
      'SCOPE_READ = "read"',
      'SCOPE_WRITE = "write"',
      "_ALLOWED_SCOPES = frozenset({SCOPE_READ, SCOPE_WRITE})",
      "",
      "",
      "@dataclass(frozen=True, slots=True)",
      "class TransferScope:",
      '    """One short-lived grant for a single LFS object."""',
      "",
      "    repository_id: str",
      "    object_id: str",
      "    action: str",
      "    expires_at: int",
      "",
      "",
      "class TransferTokenService:",
      '    """Mint and verify tokens bound to one repository and one action."""',
      "",
      "    def __init__(self, secret: str, ttl_seconds: int) -> None:",
      '        self._secret = secret.encode("utf-8")',
      "        self._ttl = ttl_seconds",
      "",
      "    def mint(self, *, repository_id: str, object_id: str, action: str) -> str:",
      "        if action not in _ALLOWED_SCOPES:",
      '            raise ValueError(f"unsupported LFS scope: {action}")',
      "        expires_at = int(time.time()) + self._ttl",
      '        payload = ":".join((repository_id, object_id, action, str(expires_at)))',
      "        signature = hmac.new(",
      '            self._secret, payload.encode("utf-8"), hashlib.sha256',
      "        ).hexdigest()",
      '        return f"{payload}:{signature}"',
      "",
      "    def verify(self, token: str, *, repository_id: str, action: str) -> TransferScope:",
      "        scope = self._parse(token)",
      "        if not hmac.compare_digest(scope.repository_id, repository_id):",
      '            raise ForbiddenError("token is bound to another repository")',
      "        if scope.expires_at < int(time.time()):",
      '            raise ForbiddenError("transfer token expired")',
      "        # A write token may also read; a read token may never write.",
      "        if scope.action not in {action, SCOPE_WRITE}:",
      '            raise ForbiddenError("transfer token scope mismatch")',
      "        return scope",
      "",
      "    def _parse(self, token: str) -> TransferScope:",
      '        parts = token.rsplit(":", 4)',
      "        if len(parts) != 5:",
      '            raise ForbiddenError("malformed transfer token")',
      "        repository_id, object_id, action, expires_at, signature = parts",
      '        payload = ":".join((repository_id, object_id, action, expires_at))',
      "        expected = hmac.new(",
      '            self._secret, payload.encode("utf-8"), hashlib.sha256',
      "        ).hexdigest()",
      "        if not hmac.compare_digest(signature, expected):",
      '            raise ForbiddenError("invalid transfer token signature")',
      "        return TransferScope(",
      "            repository_id=repository_id,",
      "            object_id=object_id,",
      "            action=action,",
      "            expires_at=int(expires_at),",
      "        )"
