      '"""Repository action matrix — the only permission decision point."""',
      "from __future__ import annotations",
      "",
      "from enum import StrEnum",
      "",
      "",
      "class Action(StrEnum):",
      '    REPO_READ = "repo:read"',
      '    REPO_WRITE = "repo:write"',
      '    REPO_ADMIN = "repo:admin"',
      '    PR_MERGE = "pr:merge"',
      '    AGENT_WRITE = "agent:write"',
      '    LFS_READ = "lfs:read"',
      '    LFS_WRITE = "lfs:write"',
      '    ISSUE_CREATE = "issue:create"',
      '    PR_CREATE = "pr:create"',
      '    COMMENT_CREATE = "comment:create"',
      "",
      "",
      "ALLOWED: dict[Action, frozenset[str]] = {",
      '    Action.REPO_READ: frozenset({"owner", "admin", "developer", "readonly"}),',
      '    Action.REPO_WRITE: frozenset({"owner", "admin", "developer"}),',
      '    Action.REPO_ADMIN: frozenset({"owner", "admin"}),',
      '    Action.PR_MERGE: frozenset({"owner", "admin", "developer"}),',
      '    Action.AGENT_WRITE: frozenset({"owner", "admin", "developer"}),',
      '    Action.LFS_READ: frozenset({"owner", "admin", "developer", "readonly"}),',
      '    Action.LFS_WRITE: frozenset({"owner", "admin", "developer"}),',
      "}",
      "",
      "_PARTICIPATION_ACTIONS = frozenset({",
      "    Action.ISSUE_CREATE,",
      "    Action.PR_CREATE,",
      "    Action.COMMENT_CREATE,",
      "})",
      "",
      "",
      "def has_repo_action(",
      "    *,",
      "    is_global_admin: bool,",
      "    is_owner: bool,",
      "    is_public: bool,",
      "    role: str | None,",
      "    action: Action,",
      ") -> bool:",
      '    """Resolve one action. This is the only place roles are compared."""',
      "    if is_global_admin or is_owner:",
      "        return True",
      "    if is_public and action in _PARTICIPATION_ACTIONS:",
      "        return True",
      '    normalized = "readonly" if role == "viewer" else role',
      "    return normalized in ALLOWED[action]"
